const aliases={"ru.history.russian-language-history.foundation.practice.01": ["индоевропейский", "индоевропейская", "индоевропейская семья", "индоевропейской семье"], "ru.history.russian-language-history.module-exam.r41-a.05": ["индоевропейский", "индоевропейская", "индоевропейская семья", "индоевропейской семье"]};
export const relaxedInput=q=>relaxedIds.has(q?.id);
export const inputAliases=q=>aliases[q?.id]??[];
export function relaxedNorm(value){return String(value??'').normalize('NFC').trim().replace(/(?<!\.)\.$/u,'').trim().replace(/\s+/gu,' ').toLocaleLowerCase('ru');}
// Keep the substantive requirements, changing only contradictory formatting directions.
